// Reads settings from environment variables at call time.
// You do NOT edit this file. Edit .env.local instead.
const num = (v: string | undefined, d: number) => {
  if (v === undefined || v.trim() === "") return d;
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

// Treat unfilled placeholders from .env.example as "not set".
const clean = (v: string | undefined) => {
  const s = (v ?? "").trim();
  return s.startsWith("PASTE_") ? "" : s;
};

export const cfg = () => ({
  geminiKey: clean(process.env.GEMINI_API_KEY),
  geminiModel: clean(process.env.GEMINI_MODEL),
  geminiFallbackModel: clean(process.env.GEMINI_FALLBACK_MODEL),
  groqKey: clean(process.env.GROQ_API_KEY),
  groqTextModel: clean(process.env.GROQ_TEXT_MODEL),
  groqVisionModel: clean(process.env.GROQ_VISION_MODEL),
  groqWhisperModel: clean(process.env.GROQ_WHISPER_MODEL),
  routeSecret: (process.env.AI_ROUTE_SECRET ?? "").trim(),
  allowedImageHosts: (process.env.ALLOWED_IMAGE_HOSTS ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean),
  timeoutMs: num(process.env.AI_TIMEOUT_MS, 20000),
  retryMs: num(process.env.AI_RETRY_MS, 1000),
  verifyMinConfidence: num(process.env.VERIFY_MIN_CONFIDENCE, 60),
  allowDefaultCache: process.env.ALLOW_DEFAULT_CACHE === "true",
  forceCache: process.env.FORCE_CACHE === "true",
});